function atoMonthlyWithholding(gross, claimsTaxFreeThreshold = true) {
  gross = Math.max(0, Number(gross) || 0);
  if (gross < 4.33) return 0;

  // Above the published table range: use NAT 1007 page 11 formulas.
  if (gross > 12675) {
    let tax;
    if (claimsTaxFreeThreshold) {
      if (gross < 15829.67) {
        tax = 3393 + 0.39 * (gross - 12675);
      } else {
        tax = 4624 + 0.47 * (gross - 15829.66);
      }
    } else {
      if (gross < 14313.00) {
        tax = 3978 + 0.39 * (gross - 12675);
      } else {
        tax = 4619 + 0.47 * (gross - 14312.99);
      }
    }
    return Math.round(tax);
  }

  // Binary search for the nearest lower earnings figure.
  let lo = 0, hi = ATO_MONTHLY_TAX_TABLE.length - 1, best = 0;
  while (lo <= hi) {
    const mid = Math.floor((lo + hi) / 2);
    if (ATO_MONTHLY_TAX_TABLE[mid][0] <= gross) {
      best = mid;
      lo = mid + 1;
    } else {
      hi = mid - 1;
    }
  }
  return ATO_MONTHLY_TAX_TABLE[best][claimsTaxFreeThreshold ? 1 : 2];
}
